<?php
declare(strict_types=1);
namespace Liberu\ControlPanel\ControlCoreFilament\Resources;
use Filament\Resources\Resource; use Filament\Schemas\Schema; use Filament\Tables\Columns\TextColumn; use Filament\Tables\Table; use Illuminate\Database\Eloquent\Builder; use Liberu\ControlPanel\ControlCore\Models\OperationTask;
final class OperationTaskResource extends Resource { protected static ?string $model=OperationTask::class; protected static string|\BackedEnum|null $navigationIcon='heroicon-o-queue-list'; protected static string|\UnitEnum|null $navigationGroup='Control Panel'; public static function form(Schema $schema):Schema{return $schema->components([]);} public static function table(Table $table):Table{return $table->columns([TextColumn::make('operation')->searchable(),TextColumn::make('status')->badge(),TextColumn::make('attempts'),TextColumn::make('finished_at')->dateTime()])->defaultSort('created_at','desc');} public static function getEloquentQuery():Builder{return parent::getEloquentQuery()->where('team_id',auth()->user()?->current_team_id);} public static function getPages():array{return ['index'=>Pages\ListOperationTasks::route('/')];} }
